function shortestTopSlice(nums: number[]): number {
  const total = new Map<number, number>();
  let degree = 0;
  for (const x of nums) { total.set(x, (total.get(x) ?? 0) + 1); degree = Math.max(degree, total.get(x)!); }
  let best = nums.length;
  for (let i = 0; i < nums.length; i++) {
    const seen = new Map<number, number>();
    for (let j = i; j < nums.length && j - i + 1 < best; j++) {
      const c = (seen.get(nums[j]) ?? 0) + 1;
      seen.set(nums[j], c);
      if (c === degree) { best = j - i + 1; break; }
    }
  }
  return best;
}

