class Solution:
    def shortestTopSlice(self, nums: List[int]) -> int:
        degree = max(Counter(nums).values())
        best = len(nums)
        for i in range(len(nums)):
            seen = defaultdict(int)
            for j in range(i, len(nums)):
                if j - i + 1 >= best:
                    break
                seen[nums[j]] += 1
                if seen[nums[j]] == degree:
                    best = j - i + 1
                    break
        return best

