function shortestTopSlice(nums: number[]): number {
  const count = new Map<number, number>(), first = new Map<number, number>();
  let degree = 0, best = 0;
  nums.forEach((x, i) => {
    if (!first.has(x)) first.set(x, i);
    const c = (count.get(x) ?? 0) + 1;
    count.set(x, c);
    const span = i - first.get(x)! + 1;
    if (c > degree) { degree = c; best = span; }
    else if (c === degree) best = Math.min(best, span);
  });
  return best;
}

